pug:
.gray-block
    p.asset.pb24.bb
        img.asset-logo-2(src="{{ image_1 }}")
        |{{ text_1 }}
    p.text.pt24 {{ text_2 }}

styl:
.bb { border-bottom: 1px solid #d9d9db; }
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb24 { padding-bottom: 24px; }
.pt24 { padding-top: 24px; }
.asset { font-family: Helvetica !important;
  font-style: normal;
  font-weight: 700;
  font-size: 18px;
  line-height: 27px;
  color: #393a44; }
.asset-logo-2 { display: inline-block;
  width: 56px !important;
  float: none;
  vertical-align: middle;
  padding-right: 12px; }
@media screen and (max-width: 600px) {
  .text.mob-text,
  .grey-text.mob-text { font-size: 17px !important; }
}
.gray-block { background: #f9f9f9 url("https://fsms.quadcode.com/storage/public/d6/0u/6tvvhhgea139ul10/link-img.png") top 24px right 24px no-repeat;
  background-size: 24px;
  padding: 24px;
  border-radius: 24px; }
